# Count consecutive foreground runs and horizontal/vertical full spans in the changed neighborhoods.
D1=['9999999999999','9999999999999','9999999999999','9994944444999','9994499494499','4444949999499','9994944494499']
D2=['5555555555555','5555555555555','5555555555555','0000050050555','0000000000005','0000005005555','0000000050555','0000000005555']
for name, rows, bg in [('D1',D1,'9'),('D2',D2,'5')]:
 print(name)
 for r,s in enumerate(rows):
  if bg in s and r>=3:
   # contiguous foreground run lengths
   vals=[(i,len(run)) for i,run in enumerate(__import__('re').finditer('[^'+bg+']+',s))]
   if any(n>=4 for _,n in vals): print(r, vals)
