 "content": "def transform(grid):
    """Mark mismatching pixels in the first of two translated repeated-pattern bands."""
    h, w = len(grid), len(grid[0]) if grid else 0
    if not h or not w:
        return []
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    # Find maximal occupied row bands separated by completely blank rows.
    bands = []
    start = None
    for r in range(h + 1):
        occupied = r < h and any(v != bg for v in grid[r])
        if occupied and start is None:
            start = r
